<?php
namespace App\Models;use App\Models\Concerns\ProtectsOfficialRegister;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
final class Carrier extends Model{use HasUuids,ProtectsOfficialRegister;protected$fillable=['party_id','cima_code','status','capabilities','canonical_id','slug','legal_name','trade_name','regulator_sequence','data_origin','source_authority','reference_year','regulatory_status','register_source','country_code','is_official_register','is_demo','insurer_code','short_name','licence_branch','currency','product_families','product_families_origin','product_families_status'];protected function casts():array{return['capabilities'=>'array','product_families'=>'array','is_official_register'=>'boolean','is_demo'=>'boolean','regulator_sequence'=>'integer','reference_year'=>'integer'];}public function party():BelongsTo{return$this->belongsTo(Party::class);}public function products():HasMany{return$this->hasMany(InsuranceProduct::class);}public function authorizations():HasMany{return$this->hasMany(InsurerAuthorization::class);}}
